import { test, expect } from '@playwright/test';

test('Invalid Email Format Rejected', async ({ page }) => {
  console.log('[Timeline] Navigate: https://www.saucedemo.com');
  await page.goto('https://www.saucedemo.com');

  // Open the registration form
  console.log('[Timeline] Action: Open registration form');
  // TODO: locator not specified in inputs — confirm against live DOM
  await page.locator('button:has-text("Register")').click();

  // Enter full name "Noah White"
  console.log('[Timeline] Action: Enter full name "Noah White"');
  // TODO: confirm that this placeholder matches the full name field
  await page.locator('input[placeholder="Full name"]').fill('Noah White');

  // Enter email "noah@example.com"
  console.log('[Timeline] Action: Enter email "noah@example.com"');
  // TODO: confirm that this placeholder matches the email field
  await page.locator('input[placeholder="Email"]').fill('noah@example.com');

  // Enter password "GreenTea!8"
  console.log('[Timeline] Action: Enter password "GreenTea!8"');
  // TODO: confirm that this placeholder matches the password field
  await page.locator('input[placeholder="Password"]').fill('GreenTea!8');

  // Confirm password "GreenTea!8"
  console.log('[Timeline] Action: Confirm password "GreenTea!8"');
  // TODO: confirm that this placeholder matches the confirm password field
  await page.locator('input[placeholder="Confirm Password"]').fill('GreenTea!8');

  // Check "Accept Terms" box
  console.log('[Timeline] Action: Check Accept Terms');
  // TODO: locator not specified in inputs — confirm against live DOM
  await page.locator('input[type="checkbox"]').check();

  // Click the Register button
  console.log('[Timeline] Action: Click Register button');
  // TODO: locator not specified in inputs — confirm against live DOM
  await page.locator('button:has-text("Register")').click();

  // Verify rejected validation error
  console.log('[Timeline] Assertion: Verify rejected validation error');
  // TODO: confirm that the error locator matches the rejected validation error
  await expect(page.locator('text=rejected_validation_error')).toBeVisible();
});
